package com.fandazi.feature.address;
import java.util.*; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/addresses") public class AddressController { private final AddressService addresses; public AddressController(AddressService addresses){this.addresses=addresses;} @GetMapping public List<AddressEntity> list(@AuthenticationPrincipal Long userId){return addresses.list(userId);}@PostMapping public ResponseEntity<AddressEntity> create(@AuthenticationPrincipal Long userId,@RequestBody AddressCommand command){return ResponseEntity.status(HttpStatus.CREATED).body(addresses.create(userId,command));}@PutMapping("/{id}") public AddressEntity update(@AuthenticationPrincipal Long userId,@PathVariable Long id,@RequestBody AddressCommand command){return addresses.update(userId,id,command);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@AuthenticationPrincipal Long userId,@PathVariable Long id){addresses.delete(userId,id);}@PatchMapping("/{id}/default") public AddressEntity setDefault(@AuthenticationPrincipal Long userId,@PathVariable Long id){return addresses.setDefault(userId,id);} }
